using Npgsql;
using SubscriptionReminders.Business;

namespace SubscriptionReminders.Data;

public sealed class PostgresSubscriptionRepository(NpgsqlDataSource dataSource) : ISubscriptionRepository
{
    public async Task InitializeAsync()
    {
        await using var command = dataSource.CreateCommand("""
            CREATE TABLE IF NOT EXISTS "Services" (
                "Id" integer PRIMARY KEY
            );
            CREATE TABLE IF NOT EXISTS "Subscriptions" (
                "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "ServiceId" integer NOT NULL REFERENCES "Services"("Id"),
                "AmountCents" integer NOT NULL CHECK ("AmountCents" > 0),
                "NextPaymentDate" date NOT NULL
            );
            INSERT INTO "Services" ("Id") VALUES (1), (2), (3)
            ON CONFLICT ("Id") DO NOTHING;
            """);
        await command.ExecuteNonQueryAsync();
    }

    public async Task<bool> ServiceExistsAsync(int id)
    {
        await using var command = dataSource.CreateCommand(
            """SELECT EXISTS (SELECT 1 FROM "Services" WHERE "Id" = $1)""");
        command.Parameters.AddWithValue(id);
        return (bool)(await command.ExecuteScalarAsync())!;
    }

    public async Task<IReadOnlyList<SubscriptionRecord>> ListAsync()
    {
        await using var command = dataSource.CreateCommand(
            """SELECT "Id", "ServiceId", "AmountCents", "NextPaymentDate" FROM "Subscriptions" ORDER BY "Id" """);
        await using var reader = await command.ExecuteReaderAsync();
        var result = new List<SubscriptionRecord>();
        while (await reader.ReadAsync())
            result.Add(Read(reader));
        return result;
    }

    public async Task<SubscriptionRecord> CreateAsync(SubscriptionInput input)
    {
        await using var command = dataSource.CreateCommand("""
            INSERT INTO "Subscriptions" ("ServiceId", "AmountCents", "NextPaymentDate")
            VALUES ($1, $2, $3)
            RETURNING "Id", "ServiceId", "AmountCents", "NextPaymentDate"
            """);
        AddInput(command, input);
        await using var reader = await command.ExecuteReaderAsync();
        await reader.ReadAsync();
        return Read(reader);
    }

    public async Task<SubscriptionRecord?> UpdateAsync(int id, SubscriptionInput input)
    {
        await using var command = dataSource.CreateCommand("""
            UPDATE "Subscriptions"
            SET "ServiceId" = $2, "AmountCents" = $3, "NextPaymentDate" = $4
            WHERE "Id" = $1
            RETURNING "Id", "ServiceId", "AmountCents", "NextPaymentDate"
            """);
        command.Parameters.AddWithValue(id);
        AddInput(command, input);
        await using var reader = await command.ExecuteReaderAsync();
        return await reader.ReadAsync() ? Read(reader) : null;
    }

    public async Task<bool> DeleteAsync(int id)
    {
        await using var command = dataSource.CreateCommand(
            """DELETE FROM "Subscriptions" WHERE "Id" = $1""");
        command.Parameters.AddWithValue(id);
        return await command.ExecuteNonQueryAsync() != 0;
    }

    private static void AddInput(NpgsqlCommand command, SubscriptionInput input)
    {
        command.Parameters.AddWithValue(input.ServiceId);
        command.Parameters.AddWithValue(input.AmountCents);
        command.Parameters.AddWithValue(input.NextPaymentDate);
    }

    private static SubscriptionRecord Read(NpgsqlDataReader reader) =>
        new(reader.GetInt32(0), reader.GetInt32(1), reader.GetInt32(2), reader.GetFieldValue<DateOnly>(3));
}
